});
const FR = { poulet: 'chicken', riz: 'rice', oeuf: 'egg', oeufs: 'egg', thon: 'tuna', boeuf: 'beef', saumon: 'salmon', poisson: 'fish', legumes: 'vegetable', pates: 'pasta', avoine: 'oat', lentilles: 'lentil', fromage: 'cheese', yaourt: 'yogurt', banane: 'banana', pomme: 'apple', patate: 'potato', dinde: 'turkey', crevettes: 'shrimp', tomate: 'tomato', tomates: 'tomato', epinards: 'spinach', lait: 'milk', petit: 'breakfast', dejeuner: 'lunch', diner: 'dinner', collation: 'snack', proteine: 'protein', proteines: 'protein', vegetarien: 'vegetarian' };
const STOP = new Set(['and', 'with', 'the', 'an', 'for', 'of', 'some', 'recipe', 'recipes', 'de', 'la', 'le', 'les', 'et', 'avec', 'du', 'des', 'un', 'une', 'pour', 'recette', 'recettes', 'au', 'aux', 'en', 'high', 'riche', 'oil', 'huile', 'salt', 'sel', 'pepper', 'poivre']);
function words(q) {
  return norm(q).split(/[^a-z0-9]+/).filter(w => w.length > 1 && !STOP.has(w)).map(w => FR[w] || w)
    .map(w => (w.length > 3 && w.endsWith('es') && /(toes|shes|ches)$/.test(w)) ? w.slice(0, -2) : (w.length > 3 && w.endsWith('s') && !w.endsWith('ss')) ? w.slice(0, -1) : w);
}
function score(r, ws) {
  const name = norm(r.name), ing = norm((r.ingredients || []).join(' ')), meta = norm([r.meal, r.category, r.cuisine, ...(r.tags || [])].join(' '));
  let s = 0;
  for (const w of ws) {
    if (['breakfast', 'lunch', 'dinner', 'snack'].includes(w)) { if (norm(r.meal) === w) s += 3; continue; }
    if (w === 'protein') { s += (r.protein || 0) / 15; continue; }
    if (name.includes(w)) s += 3; else if (ing.includes(w)) s += 2; else if (meta.includes(w)) s += 1;
  }
  return s;
}
